<?php
require_once dirname(__DIR__,2).'/core/bootstrap.php';Auth::requireLogin();$db=Database::getInstance()->pdo();if($_SERVER['REQUEST_METHOD']==='POST'){Csrf::verify($_POST['csrf_token']??'');$title=trim($_POST['title']);$amount=(float)$_POST['amount'];if($title&&$amount>0){$db->prepare('INSERT INTO expenses(category_id,user_id,title,amount,expense_date,note) VALUES(?,?,?,?,?,?)')->execute(array((int)$_POST['category_id']?:null,Auth::user()['id'],$title,$amount,$_POST['expense_date'],trim($_POST['note'])));Helper::flash('تم تسجيل المصروف.','success');}Helper::redirect('modules/expenses/index.php');}$cats=$db->query('SELECT * FROM expense_categories ORDER BY name')->fetchAll();$rows=$db->query('SELECT e.*,c.name category,u.full_name FROM expenses e LEFT JOIN expense_categories c ON c.id=e.category_id JOIN users u ON u.id=e.user_id ORDER BY expense_date DESC,e.id DESC LIMIT 100')->fetchAll();$pageTitle='المصاريف';require APP_ROOT.'/includes/header.php';?><div class="page-heading"><div><h1>المصاريف</h1><p>تسجيل ومتابعة مصاريف المقهى</p></div></div><div class="card mb-3"><div class="card-header">إضافة مصروف</div><div class="card-body"><form method="post" class="row g-3 align-items-end"><?= Helper::csrfField() ?><div class="col-md-3"><label class="form-label">البيان</label><input class="form-control" name="title" required></div><div class="col-md-2"><label class="form-label">المبلغ</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></div><div class="col-md-2"><label class="form-label">الفئة</label><select class="form-select" name="category_id"><option value="0">بدون فئة</option><?php foreach($cats as $c): ?><option value="<?= (int)$c['id'] ?>"><?= Helper::e($c['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">التاريخ</label><input class="form-control" name="expense_date" type="date" value="<?= date('Y-m-d') ?>" required></div><div class="col-md-2"><label class="form-label">ملاحظة</label><input class="form-control" name="note"></div><div class="col-md-1"><button class="btn btn-coffee w-100">حفظ</button></div></form></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>التاريخ</th><th>البيان</th><th>الفئة</th><th>المبلغ</th><th>المسجل</th><th>ملاحظة</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= Helper::e($r['expense_date']) ?></td><td><?= Helper::e($r['title']) ?></td><td><?= Helper::e($r['category']?:'—') ?></td><td class="fw-bold"><?= Helper::money($r['amount']) ?></td><td><?= Helper::e($r['full_name']) ?></td><td><?= Helper::e($r['note']) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require APP_ROOT.'/includes/footer.php';
